### Instruction:
Create a C# program which takes two strings as parameters, and returns true if the two strings are anagrams of each other.

### Input:
'listen', 'silent'

### Response:
bool AreAnagrams(string s1, string s2)
{
    if (s1.Length != s2.Length)
        return false;

    int[] a = new int[256];
    int n = s1.Length;
    for (int i = 0; i < n; i++)
    {
        int c1 = (int)s1[i];
        int c2 = (int)s2[i];

        a[c1]++;
        a[c2]--;
    }

    for (int i = 0; i < 256; i++)
    {
        if (a[i] != 0)
            return false;
    }

    return true;
}

