  const requestID = requestCounter++;
  const promise = getPromiseForRequestID<InspectedElementPayload>(
    requestID,
    'inspectedScreen',
    bridge,
    `Timed out while inspecting screen.`,
    shouldListenToPauseEvents,
  );

  bridge.send('inspectScreen', {
    requestID,
    id: arbitraryRootID,
    path,
    forceFullData,
  });

  return promise;
