    },
    logElementToConsole() {},
    getElementAttributeByPath() {},
    getElementSourceFunctionById() {},
    onErrorOrWarning,
    overrideError() {},
    overrideSuspense() {},
    overrideSuspenseMilestone() {},
    overrideValueAtPath() {},
    renamePath() {},
    renderer,
    setTraceUpdatesEnabled() {},
    setTrackedPath() {},
    startProfiling() {},
    stopProfiling() {},
    storeAsGlobal() {},
    supportsTogglingSuspense,
    updateComponentFilters() {},
    getEnvironmentNames() {
