// section -> label
const sectionLabelMap = {
  'Core Changes': 'type: next',
  'Documentation Changes': 'documentation',
  'Example Changes': 'examples',
}

const fallbackSection = 'Misc Changes'

// --------------------------------------------------

const prNumberRegex = /\(#([-0-9]+)\)$/

const getCommitPullRequest = async (commit, github) => {
  const match = prNumberRegex.exec(commit.title)

  if (!match) {
    return null
  }

  const number = parseInt(match[1], 10)

  if (!number) {
    return null
  }

  const { data } = await github.connection.pullRequests.get({
    owner: github.repoDetails.user,
    repo: github.repoDetails.repo,
    number,
  })

  return data
}

const getSectionForPullRequest = (pullRequest) => {
  const { labels } = pullRequest

  // sections defined first will take priority
  for (const [section, label] of Object.entries(sectionLabelMap)) {
    if (labels.some((prLabel) => prLabel.name === label)) {
      return section
    }
  }

  return null
}

const groupByLabels = async (commits, github) => {
  // Initialize the sections object with empty arrays
  const sections = Object.keys(sectionLabelMap).reduce((sections, section) => {
    sections[section] = []
    return sections
  }, {})
  sections.__fallback = []

  for (const commit of commits) {
    const pullRequest = await getCommitPullRequest(commit, github)

    if (pullRequest) {
      const section = getSectionForPullRequest(pullRequest)

      if (section) {
        // Add the change to the respective section
        sections[section].push({
          title: pullRequest.title,
          number: pullRequest.number,
        })

        continue
      }

      // No section found, add it to the fallback section
      sections.__fallback.push({
        title: pullRequest.title,
        number: pullRequest.number,
      })

      continue
    }

    // No Pull Request found, add it to the fallback section but without the number
    sections.__fallback.push({
      title: commit.title,
    })
  }

  return sections
}

function cleanupPRTitle(title) {
  if (title.startsWith('[Docs] ')) {
    return title.replace('[Docs] ', '')
  }

  return title
}

const buildChangelog = (sections, authors) => {
  let text = ''

  for (const section in sections) {
    const changes = sections[section]

    // No changes in this section? Don't render it
    if (changes.length === 0) {
      continue
    }

    const title = section === '__fallback' ? fallbackSection : section
    text += `### ${title}\n\n`

    for (const change of changes) {
      const numberText = change.number != null ? `: #${change.number}` : ''

      text += `- ${cleanupPRTitle(change.title)}${numberText}\n`
    }

    text += '\n'
  }

  if (authors.size > 0) {
    text += '### Credits \n\n'
    text += 'Huge thanks to '

    let index = 1
    authors.forEach((author) => {
      // GitHub links usernames if prefixed with @
      text += `@${author}`

      const penultimate = index === authors.size - 1
      const notLast = index !== authors.size

      if (penultimate) {
        // Oxford comma is applied when list is bigger than 2 names
        if (authors.size > 2) {
          text += ','
        }

        text += ' and '
      } else if (notLast) {
        text += ', '
      }

      index += 1
    })

    text += ' for helping!'
    text += '\n'
  }

  return text
}

module.exports = async (markdown, metadata) => {
  const { commits, authors, githubConnection, repoDetails } = metadata

  const github = { connection: githubConnection, repoDetails }

  const sections = await groupByLabels(commits.all, github)
  const changelog = buildChangelog(sections, authors)

  return changelog
}

#!/usr/bin/env node
/**
 * Aggregates results from sharded stats runs and posts combined comment
 *
 * Usage: node aggregate-results.js <results-dir>
 *
 * Expects JSON files named pr-stats-*.json in the results directory
 */

const path = require('path')
const fs = require('fs/promises')
const { existsSync } = require('fs')
const addComment = require('./add-comment')
const logger = require('./util/logger')

async function main() {
  const resultsDir = process.argv[2] || process.cwd()

  logger(`Aggregating results from: ${resultsDir}`)

  // Find all pr-stats-*.json files
  const files = await fs.readdir(resultsDir)
  const statsFiles = files.filter(
    (f) => f.startsWith('pr-stats-') && f.endsWith('.json')
  )

  if (statsFiles.length === 0) {
    // This can happen for docs-only changes where stats jobs are skipped
    logger('No pr-stats-*.json files found - this may be a docs-only change')
    process.exit(0)
  }

  logger(`Found ${statsFiles.length} results files: ${statsFiles.join(', ')}`)

  // Load all results
  const allData = []
  for (const file of statsFiles) {
    const filePath = path.join(resultsDir, file)
    try {
      const content = await fs.readFile(filePath, 'utf8')
      const data = JSON.parse(content)
      allData.push(data)
      logger(`Loaded ${file} successfully`)
    } catch (err) {
      logger(`Warning: Failed to load ${file}: ${err.message}`)
    }
  }

  if (allData.length === 0) {
    logger('No valid results files could be loaded')
    process.exit(1)
  }

  // Use the first file's actionInfo and statsConfig
  const { actionInfo, statsConfig } = allData[0]

  // Re-inject the GitHub token from env (it's excluded from JSON serialization for security)
  actionInfo.githubToken = process.env.PR_STATS_COMMENT_TOKEN

  // Merge results from all files
  // Each file has results array with {title, mainRepoStats, diffRepoStats, diffs}
  // We need to merge stats objects by combining their keys
  const mergedResults = []

  // Assume all files have the same number of configs with same titles
  const numConfigs = allData[0].results.length

  for (let i = 0; i < numConfigs; i++) {
    const title = allData[0].results[i].title
    const mergedMainRepoStats = {}
    const mergedDiffRepoStats = {}
    let mergedDiffs = null

    for (const data of allData) {
      const result = data.results[i]

      // Merge mainRepoStats
      if (result.mainRepoStats) {
        for (const [key, value] of Object.entries(result.mainRepoStats)) {
          if (!mergedMainRepoStats[key]) {
            mergedMainRepoStats[key] = {}
          }
          Object.assign(mergedMainRepoStats[key], value)
        }
      }

      // Merge diffRepoStats
      if (result.diffRepoStats) {
        for (const [key, value] of Object.entries(result.diffRepoStats)) {
          if (!mergedDiffRepoStats[key]) {
            mergedDiffRepoStats[key] = {}
          }
          Object.assign(mergedDiffRepoStats[key], value)
        }
      }

      // Merge diffs (just combine all diff objects)
      if (result.diffs) {
        if (!mergedDiffs) {
          mergedDiffs = {}
        }
        Object.assign(mergedDiffs, result.diffs)
      }
    }

    mergedResults.push({
      title,
      mainRepoStats: mergedMainRepoStats,
      diffRepoStats: mergedDiffRepoStats,
      diffs: mergedDiffs,
    })
  }

  logger(
    `Merged ${allData.length} result sets into ${mergedResults.length} configs`
  )

  // Post the combined comment
  await addComment(mergedResults, actionInfo, statsConfig)

  logger('Aggregation complete')
}

main().catch((err) => {
  console.error('Error aggregating results:', err)
  process.exit(1)
})

const path = require('path')
const logger = require('../util/logger')
const { diffRepoDir, allowedConfigLocations } = require('../constants')

// load stats-config
function loadStatsConfig() {
  let statsConfig
  let relativeStatsAppDir

  for (const configPath of allowedConfigLocations) {
    try {
      relativeStatsAppDir = configPath
      statsConfig = require(
        path.join(diffRepoDir, configPath, 'stats-config.js')
      )
      break
    } catch (err) {
      if (err.code !== 'MODULE_NOT_FOUND') {
        console.error('Failed to load stats-config at', configPath, err)
      }
      /* */
    }
  }

  if (!statsConfig) {
    throw new Error(
      `Failed to locate \`.stats-app\`, allowed locations are: ${allowedConfigLocations.join(
        ', '
      )}`
    )
  }

  logger(
    'Got statsConfig at',
    path.join(relativeStatsAppDir, 'stats-config.js'),
    statsConfig,
    '\n'
  )
  return { statsConfig, relativeStatsAppDir }
}

module.exports = loadStatsConfig

const path = require('path')
const fs = require('fs')
const { existsSync } = require('fs')
const exec = require('../util/exec')
const logger = require('../util/logger')
const execa = require('execa')

const mockSpan = () => ({
  traceAsyncFn: (fn) => fn(mockSpan()),
  traceFn: (fn) => fn(mockSpan()),
  traceChild: () => mockSpan(),
})

module.exports = (actionInfo) => {
  return {
    async cloneRepo(repoPath = '', dest = '', branch = '', depth = '20') {
      await fs.promises.rm(dest, { recursive: true, force: true })
      await exec(
        `git clone ${actionInfo.gitRoot}${repoPath} --single-branch --branch ${branch} --depth=${depth} ${dest}`
      )
    },
    async getLastStable() {
      const res = await fetch(
        `https://api.github.com/repos/vercel/next.js/releases/latest`,
        {
          headers: {
            'X-GitHub-Api-Version': '2022-11-28',
          },
        }
      )

      if (!res.ok) {
        throw new Error(
          `Failed to get latest stable tag ${res.status}: ${await res.text()}`
        )
      }
      const data = await res.json()
      return data.tag_name
    },
    async getCommitId(repoDir = '') {
      const { stdout } = await exec(`cd ${repoDir} && git rev-parse HEAD`)
      return stdout.trim()
    },
    async resetToRef(ref = '', repoDir = '') {
      await exec(`cd ${repoDir} && git reset --hard ${ref}`)
    },
    async mergeBranch(ref = '', origRepoDir = '', destRepoDir = '') {
      await exec(`cd ${destRepoDir} && git remote add upstream ${origRepoDir}`)
      await exec(`cd ${destRepoDir} && git fetch upstream`)

      try {
        await exec(`cd ${destRepoDir} && git merge upstream/${ref}`)
        logger('Auto merge of main branch successful')
      } catch (err) {
        logger.error('Failed to auto merge main branch:', err)

        if (err.stdout && err.stdout.includes('CONFLICT')) {
          await exec(`cd ${destRepoDir} && git merge --abort`)
          logger('aborted auto merge')
        }
      }
    },
    /**
     * Runs `pnpm pack` on each package in the `packages` folder of the provided `repoDir`
     * @param {{ repoDir: string, nextSwcVersion: null | string }} options Required options
     * @returns {Promise<Map<string, string>>} List packages key is the package name, value is the path to the packed tar file.'
     */
    async linkPackages({
      repoDir,
      nextSwcVersion: nextSwcVersionSpecified,
      parentSpan,
    }) {
      if (!parentSpan) {
        // Not all callers provide a parent span
        parentSpan = mockSpan()
      }
      /** @type {Map<string, string>} */
      const pkgPaths = new Map()
      /** @type {Map<string, { packageJsonPath: string, packagePath: string, packageJson: any, packedPackageTarPath: string }>} */
      const pkgDatas = new Map()

      let packageFolders

      try {
        packageFolders = await parentSpan
          .traceChild('read-packages-folder')
          .traceAsyncFn(() =>
            fs.promises.readdir(path.join(repoDir, 'packages'))
          )
      } catch (err) {
        if (err.code === 'ENOENT') {
          require('console').log('no packages to link')
          return pkgPaths
        }
        throw err
      }

      parentSpan.traceChild('get-pkgdatas').traceFn(() => {
        for (const packageFolder of packageFolders) {
          const packagePath = path.join(repoDir, 'packages', packageFolder)
          const packedPackageTarPath = path.join(
            packagePath,
            `${packageFolder}-packed.tgz`
          )
          const packageJsonPath = path.join(packagePath, 'package.json')

          if (!existsSync(packageJsonPath)) {
            require('console').log(`Skipping ${packageFolder}, no package.json`)
            continue
          }

          const packageJson = JSON.parse(fs.readFileSync(packageJsonPath))
          const { name: packageName } = packageJson

          pkgDatas.set(packageName, {
            packageJsonPath,
            packagePath,
            packageJson,
            packedPackageTarPath,
          })
          pkgPaths.set(packageName, packedPackageTarPath)
        }
      })

      const nextSwcVersion =
        nextSwcVersionSpecified ??
        pkgDatas.get('@next/swc')?.packedPackageTarPath ??
        null

      await parentSpan
        .traceChild('write-packagejson')
        .traceAsyncFn(async () => {
          for (const [
            packageName,
            { packageJsonPath, packagePath, packageJson },
          ] of pkgDatas.entries()) {
            // This loops through all items to get the packagedPkgPath of each item and add it to pkgData.dependencies
            for (const [
              packageName,
              { packedPackageTarPath },
            ] of pkgDatas.entries()) {
              if (
                !packageJson.dependencies ||
                !packageJson.dependencies[packageName]
              )
                continue
              // Edit the pkgData of the current item to point to the packed tgz
              packageJson.dependencies[packageName] = packedPackageTarPath
            }

            // make sure native binaries are included in local linking
            if (packageName === '@next/swc') {
              packageJson.files ||= []

              packageJson.files.push('native')

              try {
                const swcBinariesDirContents = (
                  await fs.promises.readdir(path.join(packagePath, 'native'))
                ).filter(
                  (file) => file !== '.gitignore' && file !== 'index.d.ts'
                )

                require('console').log(
                  'using swc binaries: ',
                  swcBinariesDirContents.join(', ')
                )
              } catch (err) {
                if (err.code === 'ENOENT') {
                  require('console').log('swc binaries dir is missing!')
                }
                throw err
              }
            } else if (packageName === 'next') {
              const nextSwcPkg = pkgDatas.get('@next/swc')

              console.log('using swc dep', {
                nextSwcVersion,
                nextSwcPkg,
              })
              if (nextSwcVersion) {
                Object.assign(packageJson.dependencies, {
                  // CI
                  '@next/swc-linux-x64-gnu': nextSwcVersion,
                  // Vercel issued laptops
                  '@next/swc-darwin-arm64': nextSwcVersion,
                })
              }
            }

            await fs.promises.writeFile(
              packageJsonPath,
              JSON.stringify(packageJson, null, 2),
              'utf8'
            )
          }
        })

      await parentSpan
        .traceChild('pnpm-packing')
        .traceAsyncFn(async (packingSpan) => {
          // wait to pack packages until after dependency paths have been updated
          // to the correct versions
          await Promise.all(
            Array.from(pkgDatas.entries()).map(
              async ([
                packageName,
                { packagePath: pkgPath, packedPackageTarPath: packedPkgPath },
              ]) => {
                return packingSpan
                  .traceChild('handle-package', { packageName })
                  .traceAsyncFn(async (handlePackageSpan) => {
                    /** @type {null | () => Promise<void>} */
                    let cleanup = null

                    if (packageName === '@next/swc') {
                      // next-swc uses a gitignore to prevent the committing of native builds but it doesn't
                      // use files in package.json because it publishes to individual packages based on architecture.
                      // When we used yarn to pack these packages the gitignore was ignored so the native builds were packed
                      // however npm does respect gitignore when packing so we need to remove it in this specific case
                      // to ensure the native builds are packed for use in gh actions and related scripts

                      const nativeGitignorePath = path.join(
                        pkgPath,
                        'native/.gitignore'
                      )
                      const renamedGitignorePath = path.join(
                        pkgPath,
                        'disabled-native-gitignore'
                      )

                      await handlePackageSpan
                        .traceChild('rename-gitignore')
                        .traceAsyncFn(() =>
                          fs.promises.rename(
                            nativeGitignorePath,
                            renamedGitignorePath
                          )
                        )
                      cleanup = async () => {
                        await fs.promises.rename(
                          renamedGitignorePath,
                          nativeGitignorePath
                        )
                      }
                    }

                    const options = {
                      cwd: pkgPath,
                      env: {
                        ...process.env,
                        COREPACK_ENABLE_STRICT: '0',
                      },
                    }
                    let execResult
                    try {
                      execResult = await handlePackageSpan
                        .traceChild('pnpm-pack-try-1')
                        .traceAsyncFn(() => execa('pnpm', ['pack'], options))
                    } catch {
                      execResult = await handlePackageSpan
                        .traceChild('pnpm-pack-try-2')
                        .traceAsyncFn(() => execa('pnpm', ['pack'], options))
                    }
                    const { stdout } = execResult

                    const packedFileName = stdout.trim()

                    await handlePackageSpan
                      .traceChild('rename-packed-tar-and-cleanup')
                      .traceAsyncFn(() =>
                        Promise.all([
                          fs.promises.rename(
                            path.join(pkgPath, packedFileName),
                            packedPkgPath
                          ),
                          cleanup?.(),
                        ])
                      )
                  })
              }
            )
          )
        })

      return pkgPaths
    },
  }
}

/**
 * Shared statistics utilities for benchmark measurements
 */

/**
 * Calculate statistical summary for an array of numbers
 * @param {number[]} arr - Array of numeric values
 * @returns {Object|null} Stats object with median, min, max, mean, stddev, cv or null if empty
 */
function calcStats(arr) {
  if (arr.length === 0) return null

  const sorted = [...arr].sort((a, b) => a - b)
  const mid = Math.floor(sorted.length / 2)
  const median =
    sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2
  const min = sorted[0]
  const max = sorted[sorted.length - 1]
  const mean = arr.reduce((a, b) => a + b, 0) / arr.length
  const variance =
    arr.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) / arr.length
  const stddev = Math.sqrt(variance)
  const cv = mean > 0 ? (stddev / mean) * 100 : 0 // coefficient of variation as %

  return {
    median,
    min,
    max,
    mean: Math.round(mean),
    stddev: Math.round(stddev),
    cv: Math.round(cv),
  }
}

module.exports = { calcStats }

#!/usr/bin/env node
const path = require('path')
const fs = require('fs')

const getSequenceGenerator = require('random-seed')
const generate = require('@babel/generator').default
const t = require('@babel/types')

const MIN_COMPONENT_NAME_LEN = 18
const MAX_COMPONENT_NAME_LEN = 24
const MIN_CHILDREN = 4
const MAX_CHILDREN = 80

const arrayUntil = (len) => [...Array(len)].map((_, i) => i)

const generateFunctionalComponentModule = (componentName, children = []) => {
  const body = [
    generateImport('React', 'react'),
    ...children.map((childName) => generateImport(childName, `./${childName}`)),
    t.variableDeclaration('const', [
      t.variableDeclarator(
        t.identifier(componentName),
        t.arrowFunctionExpression(
          [],
          t.parenthesizedExpression(
            generateJSXElement(
              'div',
              children.map((childName) => generateJSXElement(childName))
            )
          )
        )
      ),
    ]),
    t.exportDefaultDeclaration(t.identifier(componentName)),
  ]

  return t.program(body, [], 'module')
}

const generateJSXElement = (componentName, children = null) =>
  t.JSXElement(
    t.JSXOpeningElement(t.JSXIdentifier(componentName), [], !children),
    children ? t.JSXClosingElement(t.JSXIdentifier(componentName)) : null,
    children || [],
    !children
  )

const generateImport = (componentName, requireString) =>
  t.importDeclaration(
    [t.importDefaultSpecifier(t.identifier(componentName))],
    t.stringLiteral(requireString)
  )

const validFirstChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
const validOtherChars = validFirstChars.toLowerCase()
function generateComponentName(seqGenerator, opts) {
  const numOtherChars = seqGenerator.intBetween(opts.minLen, opts.maxLen)
  const firstChar = validFirstChars[seqGenerator.range(validFirstChars.length)]
  const otherChars = arrayUntil(numOtherChars).map(
    () => validOtherChars[seqGenerator.range(validOtherChars.length)]
  )
  return `${firstChar}${otherChars.join('')}`
}

function* generateModules(name, remainingDepth, seqGenerator, opts) {
  const filename = `${name}.${opts.extension}`
  let ast

  if (name === 'index') {
    name = 'RootComponent'
  }

  if (remainingDepth === 0) {
    ast = generateFunctionalComponentModule(name)
  } else {
    const numChildren = seqGenerator.intBetween(opts.minChild, opts.maxChild)
    const children = arrayUntil(numChildren).map(() =>
      generateComponentName(seqGenerator, opts)
    )
    ast = generateFunctionalComponentModule(name, children)

    for (const child of children) {
      yield* generateModules(child, remainingDepth - 1, seqGenerator, opts)
    }
  }

  yield {
    filename,
    content: generate(ast).code,
  }
}

function generateFuzzponents(outdir, seed, depth, opts) {
  const seqGenerator = getSequenceGenerator(seed)

  const filenames = new Set()
  for (const { filename, content } of generateModules(
    'index',
    depth,
    seqGenerator,
    opts
  )) {
    if (filenames.has(filename)) {
      throw new Error(
        `Seed "${seed}" generates output with filename collisions.`
      )
    } else {
      filenames.add(filename)
    }
    const fpath = path.join(outdir, filename)
    fs.writeFileSync(fpath, `// ${filename}\n\n${content}`)
  }
}

if (require.main === module) {
  const { outdir, seed, depth, ...opts } = require('yargs')
    .option('depth', {
      alias: 'd',
      demandOption: true,
      describe: 'component hierarchy depth',
      type: 'number',
    })
    .option('seed', {
      alias: 's',
      demandOption: true,
      describe: 'prng seed',
      type: 'number',
    })
    .option('outdir', {
      alias: 'o',
      demandOption: false,
      default: process.cwd(),
      describe: 'the directory where components should be written',
      type: 'string',
      normalize: true,
    })
    .option('minLen', {
      demandOption: false,
      default: MIN_COMPONENT_NAME_LEN,
      describe: 'the smallest acceptable component name length',
      type: 'number',
    })
    .option('maxLen', {
      demandOption: false,
      default: MAX_COMPONENT_NAME_LEN,
      describe: 'the largest acceptable component name length',
      type: 'number',
    })
    .option('minLen', {
      demandOption: false,
      default: MIN_COMPONENT_NAME_LEN,
      describe: 'the smallest acceptable component name length',
      type: 'number',
    })
    .option('maxLen', {
      demandOption: false,
      default: MAX_COMPONENT_NAME_LEN,
      describe: 'the largest acceptable component name length',
      type: 'number',
    })
    .option('minChild', {
      demandOption: false,
      default: MIN_CHILDREN,
      describe: 'the smallest number of acceptable component children',
      type: 'number',
    })
    .option('maxChild', {
      demandOption: false,
      default: MAX_CHILDREN,
      describe: 'the largest number of acceptable component children',
      type: 'number',
    })
    .option('extension', {
      default: 'jsx',
      describe: 'extension to use for generated components',
      type: 'string',
    }).argv

  fs.mkdirSync(outdir, { recursive: true })
  generateFuzzponents(outdir, seed, depth, opts)
}

module.exports = generateFuzzponents

'use client'

import { useEffect, useRef, useState } from 'react'
import { format, measure } from '../lib/measure'

function report(result, element, textarea) {
  if (!globalThis.BENCHMARK_RESULTS) {
    globalThis.BENCHMARK_RESULTS = []
  }
  globalThis.BENCHMARK_RESULTS.push(result)

  const formattedResult = format(result)
  element.textContent += `: ${formattedResult}`
  textarea.current.value += `\n    ${formattedResult}`
  console.log(formattedResult)
  element.disabled = true
}

async function measureClientButton(element, textarea, name, fn) {
  if (element.textContent.includes('Loading time')) {
    return
  }

  const result = await measure(name, fn)
  report(result, element, textarea)
}

async function measureActionButton(element, textarea, action) {
  if (element.textContent.includes('Loading time')) {
    return
  }

  const result = await action()

  report(result, element, textarea)
}

async function measureApiButton(element, textarea, url) {
  if (element.textContent.includes('Loading time')) {
    return
  }

  const result = await fetch(url).then((res) => res.json())

  report(result, element, textarea)
}

