  hydrate.onclick = render;

  loadScript(getQueryParam('reactPath'))
    .then(function () {
      if (needsReactDOM) {
        return Promise.all([
          loadScript(getQueryParam('reactDOMPath')),
          loadScript(getQueryParam('reactDOMServerPath')),
