import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseArgs } from 'node:util';
import { globSync } from 'tinyglobby';
import { compile, compileModule, parse, print, migrate } from 'svelte/compiler';

// toggle these to change what gets written to sandbox/output
const AST = false;
const MIGRATE = false;
const FROM_HTML = true;
const FROM_TREE = false;
const DEV = false;
const PRINT = false;

const argv = parseArgs({ options: { runes: { type: 'boolean' } }, args: process.argv.slice(2) });

const cwd = fileURLToPath(new URL('.', import.meta.url)).slice(0, -1);

// empty output directory
if (fs.existsSync(`${cwd}/output`)) {
	for (const file of fs.readdirSync(`${cwd}/output`)) {
		if (file === '.gitkeep') continue;
		try {
			fs.rmSync(`${cwd}/output/${file}`, { recursive: true });
		} catch {}
	}
}

/** @param {string} dir */
function mkdirp(dir) {
	try {
		fs.mkdirSync(dir, { recursive: true });
	} catch {}
}

/**
 * @param {string} file
 * @param {string} contents
 */
function write(file, contents) {
	mkdirp(path.dirname(file));
	fs.writeFileSync(file, contents);
}

const svelte_modules = globSync('**/*.svelte', { cwd: `${cwd}/src` });
const js_modules = globSync('**/*.js', { cwd: `${cwd}/src` });

for (const generate of /** @type {const} */ (['client', 'server'])) {
	console.error(`\n--- generating ${generate} ---\n`);
	for (const file of svelte_modules) {
		const input = `${cwd}/src/${file}`;
		const source = fs.readFileSync(input, 'utf-8');

		const output_js = `${cwd}/output/${generate}/${file}.js`;
		const output_map = `${cwd}/output/${generate}/${file}.js.map`;
		const output_css = `${cwd}/output/${generate}/${file}.css`;

		mkdirp(path.dirname(output_js));

		if (generate === 'client') {
			if (AST) {
				const ast = parse(source, {
					modern: true
				});

				write(
					`${cwd}/output/ast/${file}.json`,
					JSON.stringify(
						ast,
						(key, value) => (typeof value === 'bigint' ? ['BigInt', value.toString()] : value),
						'\t'
					)
				);

				if (PRINT) {
					const printed = print(ast);
					write(`${cwd}/output/printed/${file}`, printed.code);
				}
			}

			if (MIGRATE) {
				try {
					const migrated = migrate(source);
					write(`${cwd}/output/migrated/${file}`, migrated.code);
				} catch (e) {
					console.warn(`Error migrating ${file}`, e);
				}
			}
		}

		let from_html;
		let from_tree;

		if (generate === 'server' || FROM_HTML) {
			from_html = compile(source, {
				dev: DEV,
				hmr: DEV,
				filename: input,
				generate,
				runes: argv.values.runes,
				experimental: {
					async: true
				}
			});

			write(output_js, from_html.js.code + '\n//# sourceMappingURL=' + path.basename(output_map));
			write(output_map, from_html.js.map.toString());
		}

		// generate with fragments: 'tree'
		if (generate === 'client' && FROM_TREE) {
			from_tree = compile(source, {
				dev: false,
				filename: input,
				generate,
				runes: argv.values.runes,
				fragments: 'tree',
				experimental: {
					async: true
				}
			});

			const output_js = `${cwd}/output/${generate}/${file}.tree.js`;
			const output_map = `${cwd}/output/${generate}/${file}.tree.js.map`;

			write(output_js, from_tree.js.code + '\n//# sourceMappingURL=' + path.basename(output_map));
			write(output_map, from_tree.js.map.toString());
		}

		const compiled = from_html ?? from_tree;

		if (compiled) {
			for (const warning of compiled.warnings) {
				console.warn(warning.code);
				console.warn(warning.frame);
			}

			if (compiled.css) {
				write(output_css, compiled.css.code);
			}
		}
	}

	for (const file of js_modules) {
		const input = `${cwd}/src/${file}`;
		const source = fs.readFileSync(input, 'utf-8');

		const compiled = compileModule(source, {
			dev: false,
			filename: input,
			generate,
			experimental: {
				async: true
			}
		});

		const output_js = `${cwd}/output/${generate}/${file}`;

		mkdirp(path.dirname(output_js));
		write(output_js, compiled.js.code);
	}
}

// Creates a test from the existing playground. Can be called from anywhere.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

// Get the directory where this script is located
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Base paths relative to this script's location
const sandbox_dir = path.resolve(__dirname, '..');
const src_dir = path.join(sandbox_dir, 'src');
const tests_dir = path.resolve(__dirname, '../../../packages/svelte/tests');

// Get target folder from command line arguments
let target_folder = process.argv[2];
if (!target_folder) {
	console.error(
		'Please provide a target folder as an argument. Example: node create-test.js runtime-runes/my-test'
	);
	process.exit(1);
}
if (!target_folder.includes('/')) {
	target_folder = 'runtime-runes/' + target_folder;
}
if (!target_folder.startsWith('runtime-')) {
	console.error(
		'Target folder must start with "runtime-" (can only convert to these kinds of tests)'
	);
	process.exit(1);
}
target_folder = path.join(
	path.resolve(tests_dir, target_folder.split('/')[0]),
	'samples',
	target_folder.split('/')[1]
);

const exists = fs.existsSync(target_folder);

// Check if target folder already exists and ask for confirmation
if (exists) {
	console.log(`Target folder "${target_folder}" already exists.`);
	process.stdout.write('Do you want to override the existing test? (Y/n): ');

	// Read user input synchronously
	const stdin = process.stdin;
	stdin.setRawMode(true);
	stdin.resume();
	stdin.setEncoding('utf8');

	const response = await new Promise((resolve) => {
		stdin.on('data', (key) => {
			stdin.setRawMode(false);
			stdin.pause();
			process.stdout.write('\n');
			resolve(key);
		});
	});

	if (response.toLowerCase() === 'n') {
		console.log('Operation cancelled.');
		process.exit(0);
	}

	// Clear the existing target folder except for _config.js
	const files = fs.readdirSync(target_folder);
	for (const file of files) {
		if (file !== '_config.js') {
			const file_path = path.join(target_folder, file);
			fs.rmSync(file_path, { recursive: true, force: true });
		}
	}
} else {
	fs.mkdirSync(target_folder, { recursive: true });
}

// Starting file
const app_svelte_path = path.join(src_dir, 'App.svelte');
const collected_files = new Set();
const processed_files = new Set();

function collect_imports(file_path) {
	if (processed_files.has(file_path) || !fs.existsSync(file_path)) {
		return;
	}

	processed_files.add(file_path);
	collected_files.add(file_path);

	const content = fs.readFileSync(file_path, 'utf8');

	// Regex to match import statements
	const import_regex = /import\s+(?:[^'"]*\s+from\s+)?['"]([^'"]+)['"]/g;
	let match;

	while ((match = import_regex.exec(content)) !== null) {
		const import_path = match[1];

		// Skip node_modules imports
		if (!import_path.startsWith('.')) {
			continue;
		}

		// Resolve relative import path
		const resolved_path = path.resolve(path.dirname(file_path), import_path);

		// Try different extensions if file doesn't exist
		const extensions = ['', '.svelte', '.js', '.ts'];
		let actual_path = null;

		for (const ext of extensions) {
			const test_path = resolved_path + ext;
			if (fs.existsSync(test_path)) {
				actual_path = test_path;
				break;
			}
		}

		if (actual_path) {
			collect_imports(actual_path);
		}
	}
}

// Start collecting from App.svelte
collect_imports(app_svelte_path);

// Copy collected files to target folder
for (const file_path of collected_files) {
	const relative_path = path.relative(src_dir, file_path);
	let target_path = path.join(target_folder, relative_path);

	// Rename App.svelte to main.svelte
	if (path.basename(file_path) === 'App.svelte') {
		target_path = path.join(target_folder, path.dirname(relative_path), 'main.svelte');
	}

	// Ensure target directory exists
	const target_dir = path.dirname(target_path);
	if (!fs.existsSync(target_dir)) {
		fs.mkdirSync(target_dir, { recursive: true });
	}

	// Copy file
	fs.copyFileSync(file_path, target_path);
	console.log(`Copied: ${file_path} -> ${target_path}`);
}

// Create empty _config.js
if (!exists) {
	const config_path = path.join(target_folder, '_config.js');
	fs.writeFileSync(
		config_path,
		`import { test } from '../../test';

export default test({
	async test({ assert, target }) {
	}
});
`
	);
	console.log(`Created: ${config_path}`);
}

console.log(`\nTest files created in: ${target_folder}`);

import fs from 'node:fs';

/**
 * Detects if a file is text or binary by checking for null bytes
 * and validating UTF-8 encoding
 * @param {string} filepath - Path to the file
 * @returns {boolean} - true if file is text, false if binary
 */
function is_text_file(filepath) {
	const buffer = fs.readFileSync(filepath);
	// Check for null bytes which indicate binary files
	for (let i = 0; i < buffer.length; i++) {
		if (buffer[i] === 0) {
			return false;
		}
	}
	// Validate UTF-8 encoding
	try {
		const text = buffer.toString('utf-8');
		// Verify round-trip encoding to ensure valid UTF-8
		const encoded = Buffer.from(text, 'utf-8');
		return buffer.equals(encoded);
	} catch {
		return false;
	}
}

const files = [];

for (const basename of fs.readdirSync('src')) {
	if (fs.statSync(`src/${basename}`).isDirectory()) continue;

	const filepath = `src/${basename}`;
	const text = is_text_file(filepath);

	files.push({
		type: 'file',
		name: basename,
		basename,
		contents: fs.readFileSync(filepath, text ? 'utf-8' : 'base64'),
		text
	});
}

const payload = JSON.stringify({
	name: 'sandbox',
	files
});

async function compress(payload) {
	const reader = new Blob([payload])
		.stream()
		.pipeThrough(new CompressionStream('gzip'))
		.getReader();

	let buffer = '';
	for (;;) {
		const { done, value } = await reader.read();

		if (done) {
			reader.releaseLock();
			return btoa(buffer).replaceAll('+', '-').replaceAll('/', '_');
		} else {
			for (let i = 0; i < value.length; i++) {
				// decoding as utf-8 will make btoa reject the string
				buffer += String.fromCharCode(value[i]);
			}
		}
	}
}

const hash = await compress(payload);
console.log(`https://svelte.dev/playground/untitled#${hash}`);

