#[derive(FromV8, Default, Debug, Clone, Copy)]
pub struct OpenOptions {
  #[from_v8(default)]
  pub read: bool,
  #[from_v8(default)]
  pub write: bool,
  #[from_v8(default)]
  pub create: bool,
  #[from_v8(default)]
  pub truncate: bool,
  #[from_v8(default)]
  pub append: bool,
  #[from_v8(default)]
  pub create_new: bool,
  #[from_v8(default)]
  pub custom_flags: Option<i32>,
  #[from_v8(default)]
  pub mode: Option<u32>,
}

impl OpenOptions {
  pub fn read() -> Self {
    Self {
      read: true,
      write: false,
      create: false,
      truncate: false,
      append: false,
      create_new: false,
      custom_flags: None,
      mode: None,
    }
  }

  pub fn write(
    create: bool,
    append: bool,
    create_new: bool,
    mode: Option<u32>,
  ) -> Self {
    Self {
      read: false,
      write: true,
      create,
      truncate: !append,
      append,
      create_new,
      custom_flags: None,
      mode,
    }
  }
}

impl From<i32> for OpenOptions {
  fn from(flags: i32) -> Self {
    let mut options = OpenOptions {
      ..Default::default()
    };
    let mut flags = flags;

    if (flags & libc::O_APPEND) == libc::O_APPEND {
      options.append = true;
      flags &= !libc::O_APPEND;
    }
    if (flags & libc::O_CREAT) == libc::O_CREAT {
      options.create = true;
      flags &= !libc::O_CREAT;
    }
    if (flags & libc::O_EXCL) == libc::O_EXCL {
      options.create_new = true;
      options.write = true;
      flags &= !libc::O_EXCL;
    }
    if (flags & libc::O_RDWR) == libc::O_RDWR {
      options.read = true;
      options.write = true;
      flags &= !libc::O_RDWR;
    }
    if (flags & libc::O_TRUNC) == libc::O_TRUNC {
      options.truncate = true;
      flags &= !libc::O_TRUNC;
    }
    if (flags & libc::O_WRONLY) == libc::O_WRONLY {
      options.write = true;
      flags &= !libc::O_WRONLY;
    }

    if flags != 0 {
      options.custom_flags = Some(flags);
    }

    if !options.append
      && !options.create
      && !options.create_new
      && !options.read
      && !options.truncate
      && !options.write
    {
      options.read = true;
    }

    Self { ..options }
  }
}

