### Input:
Input: 1->2->3->4->5->NULL, k = 2

### Response:
public ListNode reverseKGroup(ListNode head, int k) {
    ListNode curr = head;
    ListNode prev = null;

    int count = 0;

    while (curr != null && count != k) {
        ListNode next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
        count++;
    }

    if (next != null) {
        head.next = reverseKGroup(next, k);
    }

    return prev;
}

