    int n = sizeof(arr)/sizeof(arr[0]); 

    // bubble sort algorithm 
    for (int i = 0; i < n-1; i++)      

        // Last i elements are already in place    
        for (int j = 0; j < n-i-1; j++)  
            if (arr[j] > arr[j+1]) 
                swap(arr[j], arr[j+1]); 

    cout << "Sorted array: \n"; 
    for (int i=0; i < n; i++) 
        cout << arr[i] << " "; 
    cout << endl; 

    return 0; 
}

