public static String numberToString(int num) {
    StringBuilder sb = new StringBuilder();

    // if num is negative, append '-' to sb
    if (num < 0) {
        sb.append('-');
    }

    // obtain absolute value to accommodate for all numbers
    num = Math.abs(num);

    // extract each digit and append to sb
