### Instruction:
Write a C++ program to find the elements that appear once in an array.

### Input:
arr[] = {2, 3, 4, 5, 6, 2, 3, 4};

### Response:
#include <bits/stdc++.h> 
using namespace std; 

int getSingle(int arr[], int n) 
{ 
	// initialize result 
	int result = 0; 

	// Iterate through every bit 
	for (int i = 0; i < 32; i++) 
	{ 
		// Find sum of set bits at i'th position in all 
		// array elements 
		int x = 0; 
		for (int j = 0; j < n; j++) 
			x += (arr[j] & (1 << i)); 

		// The bits with sum not multiple of 3, are the 
		// bits of element with single occurrence. 
		if (x % 3) 
			result |= (1 << i); 
	} 

	return result; 
} 

// Driver code 
int main() 
{ 
	int arr[] = {2, 3, 4, 5, 6, 2, 3, 4}; 
	int n = sizeof(arr) / sizeof(arr[0]); 
	cout << "The element with single occurrence is "
		<< getSingle(arr, n); 
}

