int length1 = a1.length;
int length2 = a2.length;

int[] mergedArray = new int[length1 + length2];

// indexes for main array 
int i = 0;
int j = 0;
int k = 0;

while (i < length1 && j < length2)
{
    if (a1[i] < a2[j]) 
    { 
        mergedArray[k] = a1[i]; 
        i++; 
    } 
    else
    { 
        mergedArray[k] = a2[j]; 
        j++; 
    } 
    k++; 
} 

