{ 
    mergedArray[k] = a2[j]; 
    j++; 
    k++; 
}

### Instruction:
Suggest code to delete an element from a linked list in Java.

### Response:
// Function to delete a node in a linked list. 
void deleteNode(Node head_ref, Node del) 
{ 
    // base case 
    if (head == null || del == null) 
        return; 

    // If node to be deleted is head node 
    if (head == del) 
        head = del.next; 

    // Change next only if node to be 
    // deleted is NOT the last node 
    if (del.next != null) 
    { 
        del.data = del.next.data; 
        del.next = del.next.next; 
    } 

    // if node to be deleted is last node 
    else
    { 
        Node temp = head; 
        while (temp.next != del) 
            temp = temp.next; 

        temp.next = null; 
    } 
    return; 
}

