### Instruction:
Create a C++ program to sort an array using selection sort algorithm.

### Input:
[2, 7, 4, 1, 5, 3]

### Response:
#include <iostream>
using namespace std;

void selectionSort(int arr[], int n)
{
    int i, j, min_idx;

    for (i = 0; i < n-1; i++)
    {
        min_idx = i;
        for (j = i+1; j < n; j++)
           if (arr[j] < arr[min_idx])
               min_idx = j;

        swap(arr[min_idx], arr[i]);
    }
}

int main()
{
    int arr[] = {2, 7, 4, 1, 5, 3};
    int n = sizeof(arr)/sizeof(arr[0]);
    selectionSort(arr, n);
    cout << "Sorted array is \n";
    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";

    return 0;
}

