#include<iostream>
using namespace std;

// Function to sort an array in ascending order
void asc_sort(int arr[], int n)
{
    int temp;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        if (arr[i] > arr[j]) {
          temp = arr[i];
          arr[i] = arr[j];
          arr[j] = temp;
        }
      }
    }
}

// Function to sort an array in descending order
void desc_sort(int arr[], int n)
{
    int temp;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
          if (arr[i] < arr[j]) {
            temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
          }
        }
      }
}

int main()
{
    int arr[] = {2, 3, 1, 5, 4};
    int n = 5;
    asc_sort(arr, n);
